package br.com.bemdoar.service;
import br.com.bemdoar.dto.*;import br.com.bemdoar.entity.*;import br.com.bemdoar.enums.*;import br.com.bemdoar.exception.*;import br.com.bemdoar.repository.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.multipart.MultipartFile;import java.nio.file.*;import java.time.LocalDateTime;import java.util.*;
@Service public class EvidenciaService{private final EvidenciaRepository repo;private final AcaoSocialRepository acoes;public EvidenciaService(EvidenciaRepository r,AcaoSocialRepository a){repo=r;acoes=a;}
 @Transactional public EvidenciaResponse enviar(Long acaoId,MultipartFile f){if(repo.countByAcaoId(acaoId)>=5)throw new RegraNegocioException("Maximo de 5 evidencias por acao.");if(f.isEmpty()||f.getSize()>5*1024*1024)throw new RegraNegocioException("O arquivo deve ter no maximo 5 MB.");Map<String,TipoEvidencia> tipos=Map.of("image/jpeg",TipoEvidencia.JPEG,"image/png",TipoEvidencia.PNG,"application/pdf",TipoEvidencia.PDF);TipoEvidencia tipo=tipos.get(f.getContentType());if(tipo==null)throw new RegraNegocioException("Tipo de arquivo nao permitido.");AcaoSocial a=acoes.findById(acaoId).orElseThrow(()->new RecursoNaoEncontradoException("Acao social nao encontrada."));try{Path pasta=Paths.get("uploads").toAbsolutePath();Files.createDirectories(pasta);String nome=UUID.randomUUID()+"-"+Paths.get(Objects.requireNonNullElse(f.getOriginalFilename(),"arquivo")).getFileName();Path destino=pasta.resolve(nome);f.transferTo(destino);Evidencia e=new Evidencia();e.setAcao(a);e.setNomeArquivo(f.getOriginalFilename());e.setTipo(tipo);e.setCaminho("/uploads/"+nome);e.setPublica(false);e.setDataUpload(LocalDateTime.now());return EvidenciaResponse.de(repo.save(e));}catch(Exception ex){throw new RegraNegocioException("Nao foi possivel salvar o arquivo.");}}
 @Transactional public EvidenciaResponse visibilidade(Long id){Evidencia e=repo.findById(id).orElseThrow(()->new RecursoNaoEncontradoException("Evidencia nao encontrada."));e.setPublica(!e.isPublica());return EvidenciaResponse.de(repo.save(e));}}
